def test_conflicting_calendar_row_requires_review():
    from twlab.calendar import classify_holiday_row,ROW_SESSION_MARKER
    row={'Date':'1150102','Name':'國曆新年開始交易日','Description':'颱風休市'}
    assert classify_holiday_row(row)!=ROW_SESSION_MARKER

def test_negated_closure_requires_review():
    from twlab.calendar import classify_holiday_row,ROW_UNKNOWN
    row={'Date':'1150102','Name':'公告','Description':'不休市，正常交易'}
    assert classify_holiday_row(row)==ROW_UNKNOWN
